{
  "technical_and_design_decisions": [
    "Implementation will be written in Go following the existing hyperledger/fabric-config codebase patterns and protobuf structures.",
    "The CLI tool will be integrated into the configtx CLI application, leveraging standard Fabric Go SDK libraries for connection profile parsing, Service Discovery config block retrieval, and transaction submission.",
    "Orderer and MSP helper methods (U7 and U8) will preserve existing configuration structs and modify internal ConfigGroups in-place without requiring full object re-serialization by the user.",
    "Consenter removal matching in U5 will enforce strict equality on host, port, client_tls_cert, and server_tls_cert bytes/strings.",
    "Unsigned ConfigUpdateEnvelope generation (U2) will construct and marshal the ConfigUpdateEnvelope protobuf without requiring any signature headers or MSP identity inputs."
  ],
  "assumptions": [
    "Development and testing will occur against Hyperledger Fabric 2.x protobuf definitions and SDKs.",
    "Existing fabric-config library architecture allows direct extensions to OrdererGroup, OrdererOrgGroup, ApplicationOrgGroup, and ConsortiumOrgGroup structs.",
    "Fabric SDK or fabric-protos-go dependencies are available and compatible for channel discovery, config block fetching, and envelope signing."
  ],
  "activities": [
    {
      "activity_id": "ACT-1",
      "activity_name": "Technical Design and API Specification",
      "activity_description": "Design function signatures for new fabric-config APIs (U1-U5, U7, U8) and define CLI parameters and batch JSON schema for the bulk updates tool (U6).",
      "most_likely_effort": 16
    },
    {
      "activity_id": "ACT-2",
      "activity_name": "Core ConfigTx Library Extensions (U1 - U5)",
      "activity_description": "Implement AddConsortium API, unsigned ConfigUpdateEnvelope generation, RemoveLegacyOrdererAddresses, RemoveKafkaBrokers, and AddConsenter/RemoveConsenter with 4-field matching.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "ACT-3",
      "activity_name": "Orderer Group Field Setter Functions (U7)",
      "activity_description": "Implement individual field mutators for OrdererGroup (SetMaxMessageCount, SetAbsoluteMaxBytes, SetPreferredMaxBytes, SetBatchTimeout, SetMaxChannels, SetConsensusType, SetConsensusState, and EtcdRaft metadata helpers).",
      "most_likely_effort": 20
    },
    {
      "activity_id": "ACT-4",
      "activity_name": "MSP Configuration Setter Functions (U8)",
      "activity_description": "Implement individual field mutators for OrdererOrgGroup, ApplicationOrgGroup, and ConsortiumOrgGroup (cert management, NodeOUs, CRL, CryptoConfig, and validation).",
      "most_likely_effort": 32
    },
    {
      "activity_id": "ACT-5",
      "activity_name": "Bulk Operations CLI Tool Implementation (U6)",
      "activity_description": "Develop the configtx update CLI tool supporting batchUpdate.json parsing, Fabric connection profile integration, service discovery config retrieval, batch channel updates, dry-run mode, and transaction submission.",
      "most_likely_effort": 56
    },
    {
      "activity_id": "ACT-6",
      "activity_name": "Documentation and Code Examples Update",
      "activity_description": "Update existing examples and add new sample code demonstrating consortium management, Orderer/MSP setter usage, Kafka-to-EtcdRaft migration, and batch CLI operation.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "ACT-7",
      "activity_name": "Unit, Integration, and End-to-End Testing",
      "activity_description": "Write comprehensive Go unit tests for all new library functions and integration tests for the CLI tool with mocked/local Fabric network setups.",
      "most_likely_effort": 36
    }
  ],
  "reported_total": {
    "most_likely_effort": 200
  }
}

